#include "source_material_keyvalues_files_candidate.h"
#include <fstream>
#include <iostream>
#include <map>
template<class T>static T read(std::istream&in){T v;if(!in.read(reinterpret_cast<char*>(&v),sizeof(v)))throw std::runtime_error("parser fixture truncated");return v;}
static std::string text(std::istream&in){auto n=read<uint32_t>(in);if(n>(1u<<24))throw std::runtime_error("source extent");std::string s(n,'\0');if(!in.read(s.data(),n))throw std::runtime_error("source truncated");return s;}
template<class T>static void put(std::ostream&out,T v){out.write(reinterpret_cast<const char*>(&v),sizeof(v));}
static void putText(std::ostream&out,const std::string&s){put(out,uint32_t(s.size()));out.write(s.data(),s.size());}
static void writeNode(std::ostream&out,const SourceMaterialPatchNodeCandidate&n){putText(out,n.key);put(out,n.kind);if(n.kind==1)putText(out,n.text);else if(n.kind==2||n.kind==3)put(out,n.bits);else if(n.kind==4||n.kind==7)put(out,n.pointer);put(out,uint32_t(n.children.size()));for(const auto&child:n.children)writeNode(out,child);}

int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"owned x64");if(argc!=3)throw std::runtime_error("catalog-and-path input output required");std::ifstream in(argv[1],std::ios::binary);std::ofstream out(argv[2],std::ios::binary);if(!in||!out)throw std::runtime_error("fixture streams");auto entries=read<uint32_t>(in);if(!entries||entries>100000)throw std::runtime_error("catalog extent");std::map<std::string,std::string>catalog;for(uint32_t i=0;i<entries;++i){auto path=text(in),source=text(in);if(!catalog.emplace(sourceMaterialKeyValuesPathCandidate(path),std::move(source)).second)throw std::runtime_error("catalog duplicate");}SourceMaterialKeyValuesSourceCandidate provider=[&](const std::string&path)->std::optional<std::string>{auto i=catalog.find(path);if(i==catalog.end())return {};return i->second;};auto cases=read<uint32_t>(in);put(out,cases);for(uint32_t i=0;i<cases;++i){auto path=text(in);auto result=sourceMaterialKeyValuesFilesCandidate(path,provider);put(out,uint32_t(1));put(out,uint32_t(result.document.roots.size()));for(const auto&root:result.document.roots)writeNode(out,root);}if(in.peek()!=std::char_traits<char>::eof())throw std::runtime_error("trailing input");out.flush();if(!out)throw std::runtime_error("output failure");std::cout<<"PASS owned file KeyValues cases="<<cases<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
